    for path in paths:
        current_path = []
        for i in range(k):
            current_path.append(path[i])
            # Check if the path is valid (i.e., within the grid boundaries)
            if not (0 <= current_path[-1] // N < N and 0 <= current_path[-1] % N < N):
                break
        else:
            if min_path is None or current_path < min_path:
                min_path = current_path
    
    return min_path

